(function(){
const general='Original teaching example; standard Japanese';
const sources={transport:'https://www.irodori.jpf.go.jp/assets/data/starter/pdf/X_L13.pdf',rail:'https://www.jreast.co.jp/multi/ticket/pdf/etiquette_e.pdf',guide:'https://www.jreast.co.jp/e/downloads/pdf/jr-east_guide_e.pdf'};
const p=([ja,kana,romaji,meaning])=>({ja,kana,romaji,meaning});
const d=(speaker,a)=>({speaker,...p(a)});
const w=(a,distractors,say)=>({kind:'word',...p(a),distractors,say,src:general,status:'general'});
const s=(a,tiles,distractors,say)=>({kind:'sentence',...p(a),tiles:tiles.map(([ja,romaji])=>({ja,romaji})),distractors:distractors.map(([ja,romaji])=>({ja,romaji})),transfer:false,say,src:general,status:'general'});
const g=(title,explanation,examples,q,options,answer,why)=>({kind:'grammar',title,explanation,examples:examples.map(p),quiz:{q,options,answer,why},say:explanation,src:general,status:'general'});
const c=(title,place,body,src,q,options,answer,why)=>({kind:'culture',title,place,body,src,quiz:{q,options,answer,why},say:body,status:'sourced'});
const q=(title,scene,prompt,options,answer)=>({kind:'scenario',title,scene,q:prompt,options:options.map(([text,why])=>({text,why})),answer,transfer:true,say:'Use the situation and relationship to choose a useful response.',src:general,status:'general'});
const lesson=(n,title,scene,mission,dialogue,items)=>({id:`u3l${n}`,title,scene,mission,dialogue,items:items.map((item,i)=>({id:`u3-${n}-${i+1}`,...item}))});
const unit={id:'u3',title:'Finding your way',blurb:'Read the signs, ask a clear question, and make the next connection.',place:'Streets, stations, and a bus stop',focus:'Locations · directions · travel questions',lessons:[
lesson(1,'Find the place','You are in a station concourse. You need the restroom before meeting your friend near an exit.','Ask where the restroom is. Then swap in eki to ask where the station is when you are outside.',[
d('You',['すみません。トイレはどこですか？','すみません。トイレはどこですか？','Sumimasen. Toire wa doko desu ka?','Excuse me. Where is the restroom?']),
d('Staff',['あちらです。','あちらです。','Achira desu.','It is over there.']),
d('You',['ありがとうございます。','ありがとうございます。','Arigatō gozaimasu.','Thank you.'])],[
w(['駅','えき','eki','Station'],['Airport','Shop','Home'],'Often appears at the end of a station name on signs.'),
w(['トイレ','トイレ','toire','Toilet / restroom'],['Ticket office','Entrance','Platform'],'A common sign and a practical word for asking a location.'),
w(['入口','いりぐち','iriguchi','Entrance'],['Exit','Stairs','Restroom'],'Iriguchi is where you enter. Recognize it as a whole word.'),
w(['出口','でぐち','deguchi','Exit'],['Entrance','Ticket','Elevator'],'Deguchi is where you leave. Stations may have several named or numbered exits.'),
s(['トイレはどこですか？','トイレはどこですか？','Toire wa doko desu ka?','Where is the restroom?'],[['トイレ','toire'],['は','wa'],['どこ','doko'],['ですか','desu ka']],[['いくら','ikura']],'Place + wa + doko desu ka asks where something is; doko is “where.”'),
g('Ask where, not how much','Doko asks a location. Ikura asks a price. Put the place you need before wa, then doko desu ka. The question works even if you do not know the full local address.',[['駅はどこですか？','えきはどこですか？','Eki wa doko desu ka?','Where is the station?'],['出口はどこですか？','でぐちはどこですか？','Deguchi wa doko desu ka?','Where is the exit?']],'Which word asks for a location?',['どこ (doko)','いくら (ikura)','二つ (futatsu)'],'どこ (doko)','Doko asks “where.” Ikura asks “how much,” and futatsu means two items.'),
c('A station serves different needs','A station concourse','Stations may have elevators and accessible restrooms. Keep routes clear for people who need them; not every access need is visible. If a route matters to you, ask staff about it.',sources.rail,'Why should an accessible route stay clear?',['People may need it even when their needs are not obvious','It is only a decorative part of the station','Everyone can use the stairs instead'],'People may need it even when their needs are not obvious','Shared facilities support needs you may not be able to see.'),
q('Find a way out','Your friend is waiting outside the station. You know you need an exit, but you cannot locate one.','Which question asks for what you need?',[
['入口はいくらですか (iriguchi wa ikura desu ka) — How much is the entrance?','This asks a price and names the entrance.'],['出口はどこですか (deguchi wa doko desu ka) — Where is the exit?','This asks for the place that leads outside.'],['トイレはありますか (toire wa arimasu ka) — Is there a restroom?','This asks about a different facility.']],1)
]),
lesson(2,'Follow a simple direction','Outside the station, a shopkeeper explains the short walk to a café. You check the turn before leaving.','Say “straight ahead, then right.” Ask “right?” to confirm if you are unsure.',[
d('You',['カフェはどこですか？','カフェはどこですか？','Kafe wa doko desu ka?','Where is the café?']),
d('Shopkeeper',['まっすぐ行って、右です。','まっすぐいって、みぎです。','Massugu itte, migi desu.','Go straight, then it is on the right.']),
d('You',['右ですね。','みぎですね。','Migi desu ne.','On the right, correct?']),
d('Shopkeeper',['はい、近くです。','はい、ちかくです。','Hai, chikaku desu.','Yes, it is nearby.'])],[
w(['右','みぎ','migi','Right'],['Left','Straight ahead','Behind'],'Migi names the right-hand side or direction.'),
w(['左','ひだり','hidari','Left'],['Right','Ahead','Upstairs'],'Hidari names the left-hand side or direction.'),
w(['まっすぐ','まっすぐ','massugu','Straight ahead'],['Turn left','Behind you','Far away'],'The small っ holds the s before sugu. Do not drop that timing.'),
w(['近く','ちかく','chikaku','Nearby'],['Far away','Tomorrow','The final stop'],'Chikaku gives a relative location, not an exact travel time.'),
s(['まっすぐ行って、右です。','まっすぐいって、みぎです。','Massugu itte, migi desu.','Go straight, then it is on the right.'],[['まっすぐ','massugu'],['行って','itte'],['右','migi'],['です','desu']],[['左','hidari']],'Itte links the first step to what follows. Learn this direction as a useful spoken chunk.'),
g('Check what you heard with ne','Adding ne can invite confirmation: migi desu ne means “On the right, correct?” Use it after repeating the part you want checked. It is not the same as introducing an entirely new question.',[['右ですね。','みぎですね。','Migi desu ne.','On the right, correct?'],['左ですね。','ひだりですね。','Hidari desu ne.','On the left, correct?']],'You think you heard “right” and want to check. Which fits?',['右ですね (migi desu ne)','左ですね (hidari desu ne)','いくらですか (ikura desu ka)'],'右ですね (migi desu ne)','Repeat the direction you think you heard and invite confirmation.'),
c('Pause before checking the map','A busy station walkway','JR East asks passengers not to walk while using a phone. Step out of the flow before studying a map. On an escalator, stand still and hold the handrail instead of treating one side as a walking lane.',sources.rail,'You need to study your map in a busy walkway. What fits this guidance?',['Keep walking while staring at the map','Pause somewhere out of the flow','Stop directly at the top of the escalator'],'Pause somewhere out of the flow','You can give the map your attention without blocking or colliding with others.'),
q('Confirm the turn','A local says “まっすぐ行って、左です” (Massugu itte, hidari desu — Go straight, then it is on the left). You want to confirm the turn.','What do you say?',[
['右ですね (migi desu ne) — On the right, correct?','That changes the stated direction.'],['近くですね (chikaku desu ne) — Nearby, correct?','That checks distance, not the turn you heard.'],['左ですね (hidari desu ne) — On the left, correct?','This repeats and confirms the direction given.']],2)
]),
lesson(3,'Is this the right train?','At a station, two trains use neighboring platforms. You ask staff whether this train goes to the airport.','Confirm whether a train goes to the airport. Then ask which platform you need.',[
d('You',['この電車は空港に行きますか？','このでんしゃはくうこうにいきますか？','Kono densha wa kūkō ni ikimasu ka?','Does this train go to the airport?']),
d('Staff',['いいえ。三番線です。','いいえ。さんばんせんです。','Iie. San-ban-sen desu.','No. Platform three.']),
d('You',['三番線ですね。','さんばんせんですね。','San-ban-sen desu ne.','Platform three, correct?']),
d('Staff',['はい。','はい。','Hai.','Yes.'])],[
w(['電車','でんしゃ','densha','Train (electric train)'],['Bus','Bicycle','Airplane'],'Densha is a common word for the trains used in everyday city travel.'),
w(['バス','バス','basu','Bus'],['Train','Taxi','Ship'],'A katakana word. This short vowel differs from the long sounds in some other loanwords.'),
w(['空港','くうこう','kūkō','Airport'],['Station','Park','Town hall'],'Both vowels are long: kū-kō.'),
w(['何番線','なんばんせん','nan-ban-sen','Which platform / track number'],['What time','How much','How many tickets'],'Use nan-ban-sen desu ka to ask which numbered track or platform you need.'),
s(['この電車は空港に行きますか？','このでんしゃはくうこうにいきますか？','Kono densha wa kūkō ni ikimasu ka?','Does this train go to the airport?'],[['この電車は','kono densha wa'],['空港に','kūkō ni'],['行きます','ikimasu'],['か','ka']],[['来ました','kimashita']],'Kono densha is “this train.” Destination + ni + ikimasu asks where it goes.'),
g('Destination + ni + ikimasu','Ni marks the destination with ikimasu, “go.” Add ka to ask whether the vehicle goes there. A destination name alone does not prove a particular train stops at your station; check the service information.',[['空港に行きます。','くうこうにいきます。','Kūkō ni ikimasu.','It goes to the airport.'],['このバスは駅に行きますか？','このバスはえきにいきますか？','Kono basu wa eki ni ikimasu ka?','Does this bus go to the station?']],'What does ni mark in kūkō ni ikimasu?',['The destination','The price','The number of travelers'],'The destination','Kūkō is where the train or person is going.'),
c('Make room at the doors','A train platform','When a train arrives, leave room for people to get off before boarding. Keep doorways and aisles clear. The aim is a usable shared space, especially when the station is busy.',sources.guide,'People are still getting off your arriving train. What should you do?',['Leave a clear path and wait for them to exit','Move into the doorway to secure your place','Place luggage in the doorway while you wait'],'Leave a clear path and wait for them to exit','Clear doorways help everyone board and leave smoothly.'),
q('A destination check','A bus is waiting near your hotel. You want to reach the station, not the airport.','Which question checks that destination?',[
['このバスは駅に行きますか (kono basu wa eki ni ikimasu ka) — Does this bus go to the station?','This names the vehicle and your intended destination.'],['空港はどこですか (kūkō wa doko desu ka) — Where is the airport?','That asks about a different destination and does not check the bus.'],['バスはいくらですか (basu wa ikura desu ka) — How much is the bus?','The fare alone cannot confirm its route.']],0)
]),
lesson(4,'A ticket to your destination','At a staffed ticket counter, you need one one-way ticket to Ueno. This is an example trip; real services and fares depend on your journey.','Ask for one one-way ticket to Ueno. Then contrast katamichi with ōfuku aloud.',[
d('You',['上野まで、片道を一枚お願いします。','うえのまで、かたみちをいちまいおねがいします。','Ueno made, katamichi o ichimai onegaishimasu.','One one-way ticket to Ueno, please.']),
d('Staff',['片道ですね。','かたみちですね。','Katamichi desu ne.','One-way, correct?']),
d('You',['はい。','はい。','Hai.','Yes.'])],[
w(['切符','きっぷ','kippu','Ticket'],['Platform','Receipt','Map'],'The small っ creates the held p in kippu. Keep your ticket as instructed during the trip.'),
w(['片道','かたみち','katamichi','One-way'],['Round trip','Every day','The opposite platform'],'This names travel in one direction, not a return journey.'),
w(['往復','おうふく','ōfuku','Round trip'],['One-way','A transfer','A station exit'],'Ōfuku includes outward and return travel as a concept; available ticket products vary.'),
w(['一枚','いちまい','ichimai','One flat item (here, one ticket)'],['One person','One station','One hundred yen'],'Mai counts flat objects such as paper tickets. It is different from the people counter.'),
s(['上野まで片道を一枚お願いします。','うえのまでかたみちをいちまいおねがいします。','Ueno made katamichi o ichimai onegaishimasu.','One one-way ticket to Ueno, please.'],[['上野まで','Ueno made'],['片道を','katamichi o'],['一枚','ichimai'],['お願いします','onegaishimasu']],[['二人','futari']],'Destination + made gives the endpoint. At a ticket counter, katamichi o ichimai names one one-way ticket.'),
g('Made gives an endpoint','Place + made means “as far as / to” that place. At a ticket counter, it specifies the destination for the requested ticket. Mai counts tickets; hitori/futari count people.',[['上野までお願いします。','うえのまでおねがいします。','Ueno made onegaishimasu.','To Ueno, please.'],['切符を一枚ください。','きっぷをいちまいください。','Kippu o ichimai kudasai.','One ticket, please.']],'Which word counts one paper ticket?',['一人 (hitori)','一枚 (ichimai)','一駅 (hitoeki)'],'一枚 (ichimai)','Mai counts flat objects such as a paper ticket; hitori is one person.'),
c('Keep the ticket for the exit','At ticket gates','With a typical paper train ticket, you retrieve it after entering the gate because it is needed again when exiting. Card journeys work differently. Follow the gates and operator instructions for the ticket you have.',sources.transport,'Your entry gate returns your paper ticket. What should you do?',['Keep it for the rest of the journey','Leave it behind because you have entered','Assume the returned ticket is a free souvenir'],'Keep it for the rest of the journey','It may be checked again at the destination.'),
q('A single outward journey','You need one ticket to Ueno and will make separate plans later. You do not want to request a round trip.','Which request matches?',[
['上野まで往復を一枚お願いします (Ueno made ōfuku o ichimai onegaishimasu) — One round-trip ticket to Ueno, please','Ōfuku requests outward and return travel.'],['二人です (futari desu) — There are two of us','This says the group size and gives no destination or ticket request.'],['上野まで片道を一枚お願いします (Ueno made katamichi o ichimai onegaishimasu) — One one-way ticket to Ueno, please','Katamichi and ichimai match one one-way ticket.']],2)
]),
lesson(5,'Ask a person, use a map','You are unsure which exit leads to a museum. You show a station staff member the museum marked on your map.','Get attention, show the map, and ask for the exit. Ask for repetition if the explanation is too fast.',[
d('You',['すみません。出口を教えてください。','すみません。でぐちをおしえてください。','Sumimasen. Deguchi o oshiete kudasai.','Excuse me. Please tell me which exit to use.']),
d('Staff',['地図はありますか？','ちずはありますか？','Chizu wa arimasu ka?','Do you have a map?']),
d('You',['はい、これです。','はい、これです。','Hai, kore desu.','Yes, this one.']),
d('Staff',['この出口です。','このでぐちです。','Kono deguchi desu.','This exit.'])],[
w(['駅員','えきいん','ekiin','Station staff member'],['A passenger','A classmate','A restaurant customer'],'The two i sounds meet in ekiin. This word identifies a person who works at the station.'),
w(['案内所','あんないじょ','annaijo','Information desk / information center'],['Restaurant','Ticket gate','Bus route'],'A useful place to ask for directions or local information.'),
w(['地図','ちず','chizu','Map'],['Ticket','A name tag','Money'],'Showing a map can make your spoken question more specific.'),
w(['教えてください','おしえてください','oshiete kudasai','Please tell me / teach me'],['Please wait','Please buy it','Please sit down'],'For directions, this asks someone to tell or show you the information.'),
s(['出口を教えてください。','でぐちをおしえてください。','Deguchi o oshiete kudasai.','Please tell me which exit to use.'],[['出口','deguchi'],['を','o'],['教えて','oshiete'],['ください','kudasai']],[['片道','katamichi']],'Name the information you need, then use oshiete kudasai to request it.'),
g('A useful request chunk: oshiete kudasai','Oshiete is the linking form of “tell/teach,” and kudasai makes it a request. You can learn the whole chunk first. Put the information wanted before o.',[['出口を教えてください。','でぐちをおしえてください。','Deguchi o oshiete kudasai.','Please tell me which exit to use.'],['名前を教えてください。','なまえをおしえてください。','Namae o oshiete kudasai.','Please tell me your name.']],'In deguchi o oshiete kudasai, what information is requested?',['The price','The exit','The number of drinks'],'The exit','Deguchi identifies the information you want.'),
c('Help begins with a question','A station information area','JR East encourages people to ask how they can help when someone needs assistance. Let the person describe what would help, and ask staff when you need support yourself. Do not infer needs from appearance alone.',sources.rail,'You notice another traveler struggling with a map. What respects their choice?',['Ask whether they would like help','Take their phone before asking','Assume they cannot understand anything'],'Ask whether they would like help','An offer lets them explain what help, if any, they want.'),
q('The map makes it specific','There are several exits. You have the museum marked on your phone, and station staff is available.','What is the most useful way to ask?',[
['Repeat “exit” without showing which destination you mean','There are several exits; the destination is missing.'],['Show the marked destination and ask 出口を教えてください (deguchi o oshiete kudasai — Please tell me which exit to use).','The map supplies the destination, and the phrase requests the route information.'],['Ask for a new ticket although your ticket is valid','That solves a different problem.']],1)
])],assessment:[
{id:'u3-check-1',...q('A bus outside a gallery','You leave a gallery and find a bus stop. You need the station. A local tells you this bus goes only to the airport.','What should you do next?',[
['Board because any bus route must pass the station','The stated route does not support that assumption.'],['Ask only how much the current bus costs','A price does not resolve the route mismatch.'],['Check another service with このバスは駅に行きますか (kono basu wa eki ni ikimasu ka — Does this bus go to the station?), using the route signs or staff to identify it.','You seek the service or route that fits your destination rather than assuming.']],2)},
{id:'u3-check-2',...q('A returned ticket and a crowded exit','Your entry gate returns your paper ticket. Later, you are unsure which exit leads to your hotel and people are flowing past.','Which plan combines the useful habits?',[
['Keep the ticket, move out of the walkway to check the map, and ask staff about the exit if needed.','You preserve the ticket and use space and assistance thoughtfully.'],['Leave the ticket at the entry gate and stop at the top of the escalator to read the map.','You may need the ticket again, and that stopping place blocks others.'],['Follow the biggest crowd without checking the destination.','The crowd may be heading to a different exit.']],0)}]};
if(typeof KOMOREBI_UNITS!=='undefined')KOMOREBI_UNITS.push(unit);if(typeof module!=='undefined')module.exports=unit;
})();
